const property = items[0].json;
const formatted = {
  title: property.title,
  description: property.description,
  price: property.price,
  location: property.location,
  specs: property.specs,
  images: property.images,
  features: property.features,
  listingType: property.listingType,
  agent: property.agent,
};

items.json = [{ formatted }];
return items;

const formatted = items.json[0];
const apiKey = $const('PRIVATE_PROPERTY_API_KEY');

if (!apiKey) {
  throw new Error('Private Property API key not configured');
}

const response = await fetch('https://api.privateproperty.co.za/v2/listings', {
  method: 'POST',
  headers: {
    'Authorization': `Bearer ${apiKey}`,
    'Content-Type': 'application/json',
  },
  body: JSON.stringify({
    listing: {
      title: formatted.title,
      description: formatted.description,
      price: formatted.price,
      listing_type: formatted.listingType,
      location: formatted.location,
      specs: formatted.specs,
      images: formatted.images,
      features: formatted.features,
    },
    contact: formatted.agent,
  }),
});

if (!response.ok) {
  throw new Error(`Private Property API error: ${response.status}`);
}

const data = await response.json();
items.json = [{ postUrl: `https://www.privateproperty.co.za/listing/${data.id}` }];
return items;

const result = {
  platform: 'private_property',
  success: true,
  postUrl: items.json[0].postUrl,
};
items.json = [result];
return items;

const result = items.json[0];
const webhookUrl = $const('WEBHOOK_URL');

if (webhookUrl) {
  await fetch(webhookUrl, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ result, platform: 'private_property' }),
  });
}

return items;
